WITH cleaned AS (SELECT *, LENGTH(status) AS status_length, DATEDIFF(CURRENT_DATE(), opened_date) / 30 AS months_since_opened_date, COALESCE(status, 'N/A') AS status_clean FROM accounts WHERE opened_date > DATE '2023-06-16') SELECT * FROM (SELECT status, account_type, status_length FROM cleaned) src PIVOT (SUM(status_length) AS value_sum, COUNT(1) AS cnt FOR account_type IN ('CHECKING' AS checking, 'SAVINGS' AS savings))
